{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2138-09-28 01:15:00",
      "speaker": "Doctor",
      "text": "Good evening, Mr. ___. I’m Dr. ___, one of your hospitalists. You’re here after your bronchoscopy today. How are you feeling?"
    },
    {
      "turn_number": 2,
      "time": "2138-09-28 01:17:00",
      "speaker": "Patient",
      "text": "Hi, doctor. I’m awake, but I can’t talk much because of the trach. I’m in more pain than last time."
    },
    {
      "turn_number": 3,
      "time": "2138-09-28 01:19:00",
      "speaker": "Doctor",
      "text": "I understand. We saw that your trachea and left mainstem were narrowed again, so they dilated them and replaced your trach tube with a longer one to bypass the tight spot."
    },
    {
      "turn_number": 4,
      "time": "2138-09-28 01:21:00",
      "speaker": "Patient",
      "text": "That makes sense. Is the new tube secure?"
    },
    {
      "turn_number": 5,
      "time": "2138-09-28 01:23:00",
      "speaker": "Doctor",
      "text": "Yes, it was placed carefully using a guide and positioned 1 cm above your carina. It’s also sutured in place and the neck strap is tight."
    },
    {
      "turn_number": 6,
      "time": "2138-09-28 01:25:00",
      "speaker": "Patient",
      "text": "Good. The pain is mainly in my chest and throat. Can I get something stronger?"
    },
    {
      "turn_number": 7,
      "time": "2138-09-28 01:27:00",
      "speaker": "Doctor",
      "text": "You’re already on IV Dilaudid, and we’ll switch you to oral oxycodone soon. We’ll keep adjusting until you’re comfortable."
    },
    {
      "turn_number": 8,
      "time": "2138-09-28 01:29:00",
      "speaker": "Patient",
      "text": "Thanks. I can sip water, but eating is hard."
    },
    {
      "turn_number": 9,
      "time": "2138-09-28 01:31:00",
      "speaker": "Doctor",
      "text": "That’s expected. We’ll keep you on liquids for now and advance as tolerated. Your main job is to rest and heal."
    },
    {
      "turn_number": 10,
      "time": "2138-09-28 08:45:00",
      "speaker": "Doctor",
      "text": "Morning, Mr. ___. Your labs show a high white count, but that’s likely from the procedure and chronic inflammation, not infection."
    },
    {
      "turn_number": 11,
      "time": "2138-09-28 08:47:00",
      "speaker": "Patient",
      "text": "Should I be on antibiotics?"
    },
    {
      "turn_number": 12,
      "time": "2138-09-28 08:49:00",
      "speaker": "Doctor",
      "text": "Not right now. You’re not febrile or producing new sputum. We’ll continue your inhaled tobramycin as part of your usual care."
    },
    {
      "turn_number": 13,
      "time": "2138-09-28 08:51:00",
      "speaker": "Patient",
      "text": "Okay. I feel okay otherwise—no shortness of breath."
    },
    {
      "turn_number": 14,
      "time": "2138-09-28 08:53:00",
      "speaker": "Doctor",
      "text": "That’s reassuring. We’ll monitor you closely. Let us know if anything changes."
    },
    {
      "turn_number": 15,
      "time": "2138-09-28 13:10:00",
      "speaker": "Doctor",
      "text": "We did a chest X-ray because your oxygen dropped a bit. It shows some atelectasis in the right base, but no pneumothorax."
    },
    {
      "turn_number": 16,
      "time": "2138-09-28 13:12:00",
      "speaker": "Patient",
      "text": "Is that serious?"
    },
    {
      "turn_number": 17,
      "time": "2138-09-28 13:14:00",
      "speaker": "Doctor",
      "text": "It’s mild and common after procedures. We’ll encourage deep breathing and suction as needed. It should improve."
    },
    {
      "turn_number": 18,
      "time": "2138-09-28 15:30:00",
      "speaker": "Patient",
      "text": "Doctor, I’m feeling sleepy and my breathing feels off."
    },
    {
      "turn_number": 19,
      "time": "2138-09-28 15:32:00",
      "speaker": "Doctor",
      "text": "Your oxygen is down to 85%. Let’s check your trach. Stay calm—we’re here to help."
    },
    {
      "turn_number": 20,
      "time": "2138-09-28 15:35:00",
      "speaker": "Doctor",
      "text": "We’re giving you oxygen and bagging through the trach. Your ABG shows very high CO2—119—and low pH. This is respiratory failure."
    },
    {
      "turn_number": 21,
      "time": "2138-09-28 15:37:00",
      "speaker": "Patient",
      "text": "Is my trach out?"
    },
    {
      "turn_number": 22,
      "time": "2138-09-28 15:39:00",
      "speaker": "Doctor",
      "text": "It’s displaced. We’re taking you for an urgent bronchoscopy to reposition it. You’ll be sedated."
    },
    {
      "turn_number": 23,
      "time": "2138-09-28 17:00:00",
      "speaker": "Doctor",
      "text": "You’re back in your room. The bronchoscopy confirmed your trach had moved up. We replaced it and dilated the stenosis again."
    },
    {
      "turn_number": 24,
      "time": "2138-09-28 17:02:00",
      "speaker": "Patient",
      "text": "Is it secure now?"
    },
    {
      "turn_number": 25,
      "time": "2138-09-28 17:04:00",
      "speaker": "Doctor",
      "text": "Yes, it’s sutured in place. You were on the ventilator briefly but are now off and breathing on your own."
    },
    {
      "turn_number": 26,
      "time": "2138-09-28 17:06:00",
      "speaker": "Patient",
      "text": "Good. I’m still tired."
    },
    {
      "turn_number": 27,
      "time": "2138-09-28 17:08:00",
      "speaker": "Doctor",
      "text": "That’s expected. You’ll be moved to the ICU for close monitoring tonight."
    },
    {
      "turn_number": 28,
      "time": "2138-09-29 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re stable. A bedside bronchoscopy confirmed the trach is in the right spot."
    },
    {
      "turn_number": 29,
      "time": "2138-09-29 09:02:00",
      "speaker": "Patient",
      "text": "Can I go back to the floor?"
    },
    {
      "turn_number": 30,
      "time": "2138-09-29 09:04:00",
      "speaker": "Doctor",
      "text": "Yes, once we wean you fully off the vent. You’re already breathing well on your trach mask."
    },
    {
      "turn_number": 31,
      "time": "2138-09-29 14:00:00",
      "speaker": "Doctor",
      "text": "You’re back on the floor. Your oxygen levels are stable on room air during the day."
    },
    {
      "turn_number": 32,
      "time": "2138-09-29 14:02:00",
      "speaker": "Patient",
      "text": "That’s great. How’s my heart? I saw monitors beeping."
    },
    {
      "turn_number": 33,
      "time": "2138-09-29 14:04:00",
      "speaker": "Doctor",
      "text": "You had a brief episode of atrial flutter—fast heart rhythm—but it resolved on its own and didn’t cause symptoms."
    },
    {
      "turn_number": 34,
      "time": "2138-09-29 14:06:00",
      "speaker": "Patient",
      "text": "Should I be worried?"
    },
    {
      "turn_number": 35,
      "time": "2138-09-29 14:08:00",
      "speaker": "Doctor",
      "text": "Not acutely. Your echo showed strong heart function. We’ll check with cardiology about a monitor after discharge."
    },
    {
      "turn_number": 36,
      "time": "2138-09-30 10:00:00",
      "speaker": "Doctor",
      "text": "Your repeat labs look much better. White count is down to 7.7, and your kidneys are fine."
    },
    {
      "turn_number": 37,
      "time": "2138-09-30 10:02:00",
      "speaker": "Patient",
      "text": "That’s good. My pain is better with oxycodone every 4 hours."
    },
    {
      "turn_number": 38,
      "time": "2138-09-30 10:04:00",
      "speaker": "Doctor",
      "text": "We’ll keep that as needed. You’re also on Tylenol and ibuprofen. No signs of sedation, which is good."
    },
    {
      "turn_number": 39,
      "time": "2138-10-01 09:30:00",
      "speaker": "Doctor",
      "text": "We noticed your trach shifted slightly again—about 1 cm out. We did another bedside bronchoscopy and adjusted it."
    },
    {
      "turn_number": 40,
      "time": "2138-10-01 09:32:00",
      "speaker": "Patient",
      "text": "Again? Why does this keep happening?"
    },
    {
      "turn_number": 41,
      "time": "2138-10-01 09:34:00",
      "speaker": "Doctor",
      "text": "The tissue is fragile from repeated procedures. This time we used a shorter Portex tube and redilated the area."
    },
    {
      "turn_number": 42,
      "time": "2138-10-01 09:36:00",
      "speaker": "Patient",
      "text": "Is it stable now?"
    },
    {
      "turn_number": 43,
      "time": "2138-10-01 09:38:00",
      "speaker": "Doctor",
      "text": "Yes, and we’ll monitor closely. You’ve been off the vent since yesterday and are breathing well."
    },
    {
      "turn_number": 44,
      "time": "2138-10-02 12:15:00",
      "speaker": "Doctor",
      "text": "You had another dilation today to keep the airway open. No complications."
    },
    {
      "turn_number": 45,
      "time": "2138-10-02 12:17:00",
      "speaker": "Patient",
      "text": "How often will I need these?"
    },
    {
      "turn_number": 46,
      "time": "2138-10-02 12:19:00",
      "speaker": "Doctor",
      "text": "Monthly for now. Your pulmonologist will coordinate. We’re also following up on a biopsy from earlier."
    },
    {
      "turn_number": 47,
      "time": "2138-10-03 08:00:00",
      "speaker": "Doctor",
      "text": "Your TSH came back normal, so the arrhythmia isn’t thyroid-related."
    },
    {
      "turn_number": 48,
      "time": "2138-10-03 08:02:00",
      "speaker": "Patient",
      "text": "So what caused it?"
    },
    {
      "turn_number": 49,
      "time": "2138-10-03 08:04:00",
      "speaker": "Doctor",
      "text": "We don’t always find a cause. It could be from stress on your system. Since your stroke risk is low, we won’t start blood thinners."
    },
    {
      "turn_number": 50,
      "time": "2138-10-04 09:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re planning for discharge tomorrow if all stays stable."
    },
    {
      "turn_number": 51,
      "time": "2138-10-04 09:02:00",
      "speaker": "Patient",
      "text": "Great. Can I get my tobramycin nebs at home?"
    },
    {
      "turn_number": 52,
      "time": "2138-10-04 09:04:00",
      "speaker": "Doctor",
      "text": "We’re working on that. Your pharmacy hasn’t stocked it. We’ll help you get it sorted."
    },
    {
      "turn_number": 53,
      "time": "2138-10-04 09:06:00",
      "speaker": "Patient",
      "text": "Thanks. And my follow-up?"
    },
    {
      "turn_number": 54,
      "time": "2138-10-04 09:08:00",
      "speaker": "Doctor",
      "text": "You’ll see pulmonology for your next bronchoscopy and rheumatology for your relapsing polychondritis."
    },
    {
      "turn_number": 55,
      "time": "2138-10-05 10:00:00",
      "speaker": "Doctor",
      "text": "Final check: your breathing is stable, labs are normal, and you’re alert and comfortable."
    },
    {
      "turn_number": 56,
      "time": "2138-10-05 10:02:00",
      "speaker": "Patient",
      "text": "I feel ready to go home."
    },
    {
      "turn_number": 57,
      "time": "2138-10-05 10:04:00",
      "speaker": "Doctor",
      "text": "We’ll discharge you tomorrow. You’ll take oxycodone for pain, and all your other meds continue as before."
    },
    {
      "turn_number": 58,
      "time": "2138-10-05 10:06:00",
      "speaker": "Patient",
      "text": "And the heart monitor?"
    },
    {
      "turn_number": 59,
      "time": "2138-10-05 10:08:00",
      "speaker": "Doctor",
      "text": "We’ll arrange a 30-day event monitor. Call if you feel palpitations or dizziness."
    },
    {
      "turn_number": 60,
      "time": "2138-10-06 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared to go home. Your trach is secure, and you’re maintaining oxygen on room air."
    },
    {
      "turn_number": 61,
      "time": "2138-10-06 08:02:00",
      "speaker": "Patient",
      "text": "Thank you. I’ll follow up with my doctors."
    },
    {
      "turn_number": 62,
      "time": "2138-10-06 08:04:00",
      "speaker": "Doctor",
      "text": "Exactly. Keep using your duonebs, Esbriet, and nebulized tobramycin. Call if you have breathing trouble or trach issues."
    },
    {
      "turn_number": 63,
      "time": "2138-10-06 08:06:00",
      "speaker": "Patient",
      "text": "I will. I appreciate all the care."
    },
    {
      "turn_number": 64,
      "time": "2138-10-06 08:08:00",
      "speaker": "Doctor",
      "text": "You did well. Take it easy, and we’ll see you in clinic soon."
    },
    {
      "turn_number": 65,
      "time": "2138-10-06 08:10:00",
      "speaker": "Patient",
      "text": "Will do. Thanks again."
    },
    {
      "turn_number": 66,
      "time": "2138-10-06 08:12:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Have a safe trip home."
    },
    {
      "turn_number": 67,
      "time": "2138-10-06 08:14:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 68,
      "time": "2138-10-06 08:16:00",
      "speaker": "Doctor",
      "text": "One last thing—your discharge summary says you were admitted because the trach was out of position and you had trouble breathing."
    },
    {
      "turn_number": 69,
      "time": "2138-10-06 08:18:00",
      "speaker": "Patient",
      "text": "That’s accurate."
    },
    {
      "turn_number": 70,
      "time": "2138-10-06 08:20:00",
      "speaker": "Doctor",
      "text": "And we fixed it with bronchoscopy and repositioning. You’re on your way to recovery."
    },
    {
      "turn_number": 71,
      "time": "2138-10-06 08:22:00",
      "speaker": "Patient",
      "text": "I feel lucky to have such a good team."
    },
    {
      "turn_number": 72,
      "time": "2138-10-06 08:24:00",
      "speaker": "Doctor",
      "text": "We’re glad you’re doing well. Take care."
    },
    {
      "turn_number": 73,
      "time": "2138-10-06 08:26:00",
      "speaker": "Patient",
      "text": "You too."
    },
    {
      "turn_number": 74,
      "time": "2138-10-06 08:28:00",
      "speaker": "Doctor",
      "text": "Nurse will bring your discharge papers and prescriptions shortly."
    },
    {
      "turn_number": 75,
      "time": "2138-10-06 08:30:00",
      "speaker": "Patient",
      "text": "Okay, I’ll wait."
    },
    {
      "turn_number": 76,
      "time": "2138-10-06 08:32:00",
      "speaker": "Doctor",
      "text": "Remember to keep your trach secure and the neck strap snug."
    },
    {
      "turn_number": 77,
      "time": "2138-10-06 08:34:00",
      "speaker": "Patient",
      "text": "I’ll check it often."
    },
    {
      "turn_number": 78,
      "time": "2138-10-06 08:36:00",
      "speaker": "Doctor",
      "text": "Perfect. And use your home trach mask at night as prescribed."
    },
    {
      "turn_number": 79,
      "time": "2138-10-06 08:38:00",
      "speaker": "Patient",
      "text": "I will. Thanks for everything."
    },
    {
      "turn_number": 80,
      "time": "2138-10-06 08:40:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Stay safe and healthy."
    },
    {
      "turn_number": 81,
      "time": "2138-10-06 08:42:00",
      "speaker": "Patient",
      "text": "I will."
    },
    {
      "turn_number": 82,
      "time": "2138-10-06 08:44:00",
      "speaker": "Doctor",
      "text": "Take care, Mr. ___."
    },
    {
      "turn_number": 83,
      "time": "2138-10-06 08:46:00",
      "speaker": "Patient",
      "text": "You too, doctor."
    },
    {
      "turn_number": 84,
      "time": "2138-10-06 08:48:00",
      "speaker": "Doctor",
      "text": "We’ll be in touch with your outpatient team."
    },
    {
      "turn_number": 85,
      "time": "2138-10-06 08:50:00",
      "speaker": "Patient",
      "text": "Appreciate it."
    }
  ],
  "summary": {
    "admission_start": "2138-09-28 00:57:00",
    "admission_end": "2138-10-06 17:30:00",
    "summary_paragraph": "Mr. ___ was admitted for post-procedural monitoring following an elective bronchoscopy with tracheal and left mainstem bronchus dilation and tracheostomy exchange due to recurrent tracheobronchomalacia from Ruvalcaba-Myhre-Smith syndrome and relapsing polychondritis. His hospital course was complicated by acute hypercapnic respiratory failure on hospital day 1 due to tracheostomy dislodgment, requiring urgent bronchoscopy and temporary mechanical ventilation. He had a brief episode of asymptomatic atrial flutter, which resolved without intervention. After repeated airway interventions and stabilization, his respiratory status improved, and he was weaned off support. He was discharged home in stable condition with a secure tracheostomy, able to maintain oxygenation on room air during the day and using his home trach mask at night.",
    "problems": [
      "Other specified diseases of upper respiratory tract",
      "Acute respiratory failure with hypercapnia",
      "Acute respiratory failure with hypoxia",
      "Unspecified atrial flutter",
      "Malfunction of tracheostomy stoma",
      "Ruvalcaba-Myhre-Smith syndrome",
      "Relapsing polychondritis",
      "Essential (primary) hypertension",
      "Gastro-esophageal reflux disease without esophagitis",
      "Carrier of other specified bacterial diseases"
    ]
  }
}
